# Use ...name to collect remaining args into a list
fn sum(...numbers) {
    total = 0
    for n in numbers {
        total = total + n
    }
    return total
}

print(sum(1, 2, 3))      # 6
print(sum(10, 20))        # 30
print(sum(5))             # 5

