# match arms support full expressions: calls, ops, methods
fn classify(x) {
    return match x {
        0 => "zero",
        1 => "one",
        2 => "two",
        _ => "other"
    }
}

print(classify(0))   # "zero"
print(classify(1))   # "one"
print(classify(99))  # "other"

fn respond(cmd) {
    return match cmd {
        "start" => "Starting...",
        "stop" => "Stopping...",
        "status" => "Running",
        _ => "Unknown command"
    }
}

print(respond("start"))   # "Starting..."
print(respond("quit"))    # "Unknown command"

fn to_word(b) {
    return match b {
        true => "yes",
        false => "no",
        _ => "unknown"
    }
}
print(to_word(true))  # "yes"

# Match can destructure lists into head and rest
fn first_element(lst) {
    return match lst {
        [] => "empty",
        [x] => x,
        [x, y] => x,
        [first, ...rest] => first,
        _ => none
    }
}

print(first_element([]))         # "empty"
print(first_element([42]))       # 42
print(first_element([1, 2, 3]))  # 1

# The rest pattern captures remaining elements
fn list_length(lst) {
    return match lst {
        [] => 0,
        [_] => 1,
        [_, _] => 2,
        _ => 3
    }
}

print(list_length([]))         # 0
print(list_length([42]))       # 1
print(list_length([1, 2]))     # 2
print(list_length([1, 2, 3]))  # 3

fn is_present(value) {
    return match value {
        none => false,
        _ => true
    }
}

print(is_present(42))    # true
print(is_present(none))  # false

