# Catch specific error types
try {
    raise ValueError("invalid input")
} catch ValueError as e {
    print("Value error: " + e.message())
} catch as e {
    print("Other error: " + e.message())
}

fn validate_age(age) {
    if age < 0 {
        raise ValueError("age must be positive")
    }
    return age
}

try {
    validate_age(-5)
} catch ValueError as e {
    print(e.message())  # "age must be positive"
}

# Available error types:
# ValueError, TypeError, IOError, NetworkError,
# ParseError, RuntimeError, FileError, NetError

fn risky_operation(input) {
    if input == "type" {
        raise TypeError("wrong type")
    }
    if input == "value" {
        raise ValueError("bad value")
    }
    if input == "io" {
        raise IOError("disk full")
    }
    return "ok"
}

try {
    risky_operation("value")
} catch TypeError as e {
    print("Type: " + e.message())
} catch ValueError as e {
    print("Value: " + e.message())
} catch IOError as e {
    print("IO: " + e.message())
} catch as e {
    print("Other: " + e.message())
}

# finally always runs, even after an error
try {
    print("doing work")
    raise ValueError("oops")
} catch as e {
    print("caught: " + e.message())
} finally {
    print("cleanup always runs")
}

try {
    try {
        raise ValueError("original error")
    } catch as e {
        print("Caught: " + e.message())
        raise e  # re-raise the same error
    }
} catch as e {
    print("Re-caught: " + e.message())
}

try {
    raise ValueError("something went wrong")
} catch as e {
    print(e.type())          # "ValueError"
    print(e.message())       # "something went wrong"
    print(e.stack_trace())   # call stack at raise time
}

fn fibonacci(n) {
    if n <= 1 {
        return n
    }
    return fibonacci(n - 1) + fibonacci(n - 2)
}

print(fibonacci(10))  # 55

