# priv fn makes a function private to the current module/scope
priv fn internal_helper(x) {
    return x * 2
}

fn public_api(x) {
    return internal_helper(x) + 1
}

print(public_api(5))  # 11

fn divide(a, b) {
    if b == 0 {
        raise ValueError("Cannot divide by zero")
    }
    if a.type() != "num" {
        raise TypeError("Expected number, got " + a.type())
    }
    return a / b
}

try {
    print(divide(10, 2))    # 5
    print(divide(10, 0))    # raises ValueError
} catch ValueError as e {
    print("Value error: " + e.message())
} catch TypeError as e {
    print("Type error: " + e.message())
}

