# Yes! Match arms support full expressions including function calls
fn double(n) { return n * 2 }
fn negate(n) { return -n }

fn transform(op, value) {
    return match op {
        "double" => double(value),
        "negate" => negate(value),
        "square" => value * value,
        _ => value
    }
}

print(transform("double", 5))   # 10
print(transform("negate", 3))   # -3
print(transform("square", 4))   # 16
print(transform("other", 7))    # 7

# Match arms support binary operations, method calls, and more
fn score_grade(grade) {
    return match grade {
        "A" => 90 + 10,
        "B" => 80 + 5,
        "C" => 70 + 0,
        "D" => 50 + 10,
        _ => 0
    }
}

print(score_grade("A"))  # 100
print(score_grade("B"))  # 85
print(score_grade("F"))  # 0

# Match arms can contain method calls and chained expressions
fn describe(value) {
    return match value.type() {
        "string" => "text of length " + value.length().to_string(),
        "num" => "number: " + value.to_string(),
        "list" => "list with " + value.length().to_string() + " items",
        _ => "unknown type"
    }
}

print(describe("hello"))    # "text of length 5"
print(describe(42))         # "number: 42"
print(describe([1, 2, 3]))  # "list with 3 items"

# Match arms can return lists, maps, or any expression result
fn make_response(status) {
    return match status {
        200 => {"ok": true, "code": 200},
        404 => {"ok": false, "code": 404},
        500 => {"ok": false, "code": 500},
        _ => {"ok": false, "code": status}
    }
}

resp = make_response(200)
print(resp["ok"])    # true
print(resp["code"])  # 200

resp = make_response(404)
print(resp["ok"])    # false

# Match arms can contain other match expressions
fn classify(category, value) {
    return match category {
        "size" => match value {
            "S" => "Small",
            "M" => "Medium",
            "L" => "Large",
            _ => "Unknown size"
        },
        "color" => match value {
            "R" => "Red",
            "G" => "Green",
            "B" => "Blue",
            _ => "Unknown color"
        },
        _ => "Unknown category"
    }
}

print(classify("size", "M"))    # "Medium"
print(classify("color", "R"))   # "Red"
print(classify("other", "X"))   # "Unknown category"

# Match arms support indexing into lists and maps
colors = ["red", "green", "blue"]
fn color_name(idx) {
    return match idx {
        0 => colors[0],
        1 => colors[1],
        2 => colors[2],
        _ => "unknown"
    }
}

print(color_name(0))  # "red"
print(color_name(2))  # "blue"
print(color_name(5))  # "unknown"

# Each arm can have arbitrarily complex expressions
fn fibonacci_hint(n) {
    return match n {
        0 => 0,
        1 => 1,
        2 => 1,
        3 => 2,
        _ => n * (n - 1)
    }
}

print(fibonacci_hint(0))   # 0
print(fibonacci_hint(3))   # 2
print(fibonacci_hint(10))  # 90
